class Solution { public List<Integer> peopleIndexes(List<List<String>> favoriteCompanies){List<Set<String>> sets=new ArrayList<>();for(List<String> companies:favoriteCompanies)sets.add(new HashSet<>(companies));List<Integer> answer=new ArrayList<>();for(int i=0;i<sets.size();i++){boolean subset=false;for(int j=0;j<sets.size()&&!subset;j++)if(i!=j&&sets.get(j).size()>=sets.get(i).size()&&sets.get(j).containsAll(sets.get(i)))subset=true;if(!subset)answer.add(i);}return answer;} }
